---@meta proteus
-- Type annotations for the Proteus Lua API (lua-language-server).
-- Generated by `proteus --emit-lua-types DIR`; do not edit.
-- Use: `local p = require("proteus")` in $XDG_CONFIG_HOME/proteus/init.lua.

---@class proteus.Pane
---@field id integer
---@field title string What the tab bar shows.
---@field name string? Set by the user.
---@field cwd string? Working directory.
---@field remote string? Host of the cwd (OSC 7) when it is not this machine.
---@field process string? Foreground program (the shell when idle).
---@field command string? Command line of the running command (shell integration).
---@field window integer
---@field tab integer 1-based tab index in its window.
---@field focused boolean Focused pane of the active tab of its window.
---@field floating boolean
---@field cols integer
---@field rows integer
local Pane = {}

---All fields at once; nil once the pane is gone.
---@return table?
function Pane:info() end
---@return boolean
function Pane:exists() end

---@class proteus.SpawnOpts
---@field cmd (string|string[])? A shell command line, or program and arguments. Default: the shell.
---@field cwd string? Default: the directory of the focused pane.

---@class proteus.SplitOpts: proteus.SpawnOpts
---@field dir ("right"|"down")? Default: along the longer side.

---Split this pane; the new pane gets the focus.
---@param opts proteus.SplitOpts?
---@return proteus.Pane
function Pane:split(opts) end
---Type text into the pane as if typed ("\r" is Enter).
---@param text string
function Pane:send_text(text) end
---Paste text into the pane (bracketed paste if the application enabled it).
---@param text string
function Pane:insert_text(text) end
function Pane:close() end
function Pane:focus() end
---@param name string? nil or "" goes back to the automatic title.
function Pane:set_name(name) end
---The screen text, with up to `scrollback` lines above it.
---@param opts { scrollback: integer? }?
---@return string?
function Pane:read_screen(opts) end

---@class proteus.Block
---@field id integer
---@field command string?
---@field cwd string?
---@field exit_code integer?
---@field duration number? Seconds.
---@field block integer? Block id (for `pane:block_text`).
---@field state ("prompt"|"input"|"running"|"finished")?
---@field state "prompt"|"input"|"running"|"finished"

---Command blocks (shell integration), oldest first.
---@return proteus.Block[]
function Pane:read_blocks() end
---@param block integer Block id.
---@param part ("command"|"output"|"all")? Default "output".
---@return string?
function Pane:block_text(block, part) end

---@class proteus.Ctx
---@field pane proteus.Pane? The focused pane.

---@alias proteus.Event
---| "pane_opened"      # { pane }
---| "pane_closed"      # { pane } (gone: only `id` works)
---| "focus_changed"    # { pane, previous }
---| "cwd_changed"      # { pane, cwd }
---| "title_changed"    # { pane, title }
---| "command_started"  # { pane, command }
---| "command_finished" # { pane, command, exit_code, duration }
---| "bell"             # { pane }
---| "config_changed"   # {} after a reload
---| "block_state_changed" # { pane, block, state } a prompt, command or result began

---@class proteus.EventData
---@field name proteus.Event
---@field pane proteus.Pane?
---@field previous proteus.Pane?
---@field cwd string?
---@field title string?
---@field command string?
---@field exit_code integer?
---@field duration number? Seconds.

---@class proteus.Timer
local Timer = {}
function Timer:stop() end

---@class proteus.Config
---@field font { family: string?, size: number?, ligatures: boolean? }?
---@field cursor { blink: (boolean|"app")? }?
---@field text { grapheme_clustering: boolean?, ambiguous_width: (1|2)? }?
---@field clipboard { osc52_read: ("ask"|"allow"|"deny")?, osc52_write: boolean?, paste_protection: boolean? }?
---@field shell { command: (string|string[])?, integration: boolean? }?
---@field scrollback integer?
---@field ui { hint_bar: ("in-mode"|"always"|"never")?, tab_bar: ("auto"|"always"|"never")?, pane_titles: ("auto"|"always"|"never")?, gutter: number? }?
---@field panes { confirm_close: boolean?, confirm_close_ignore: string[]?, keep_last_shell: boolean? }?
---@field session { restore: ("ask"|"always"|"never")?, restore_commands: string[]? }?
---@field notify { min_duration: (number|false)?, osc: boolean? }?
---@field bell { visual: boolean? }?
---@field graphics { enabled: boolean?, max_image: number?, pane_memory: number?, total_memory: number?, gpu_memory: number?, local_files: boolean? }?
---@field hints { alphabet: string?, patterns: { name: string?, regex: string, url: string? }[]? }?
---@field keys table? preset, leader, sticky, and per-mode tables of key = action name.

---@alias proteus.Color integer|string A palette index 0-255 or "#rrggbb".

---@class proteus.Span
---@field [1] string? the text (or `text`)
---@field text string?
---@field fg proteus.Color?
---@field bg proteus.Color?
---@field link string? opened with Ctrl+click
---@field bold boolean?
---@field dim boolean?
---@field italic boolean?
---@field underline boolean?
---@field reverse boolean?
---@field strike boolean?

---@alias proteus.Line string|proteus.Span|(string|proteus.Span)[]

---@class proteus.UiEvent
---@field type "key"|"text"|"preedit"|"mouse"|"resize"|"focus"|"close"|"drop"
---@field key string? key: `a`, `enter`, `escape`, `up`, `page-down`, `f5`, ...
---@field text string? key, text: what was typed; preedit: the composition (nil: it ended)
---@field cursor integer? preedit: byte offset of its cursor
---@field mods { shift: boolean, ctrl: boolean, alt: boolean, logo: boolean }? key, mouse
---@field repeat boolean? key
---@field button ("left"|"middle"|"right"|"wheel_up"|"wheel_down")? mouse
---@field action ("press"|"release"|"drag")? mouse
---@field col integer? mouse (1-based)
---@field row integer? mouse (1-based)
---@field cols integer? resize
---@field rows integer? resize
---@field focused boolean? focus
---@field paths string[]? drop

---@class proteus.SurfaceOpts
---@field kind ("float"|"sidebar_left"|"sidebar_right"|"overlay"|"pane_right"|"pane_down"|"tab")? default "float"
---@field title string?
---@field cols integer? sidebars: width; floats and overlays: width (default 40)
---@field rows integer? floats and overlays: height (0: 10)
---@field focus boolean? take the keyboard (default true)
---@field pane (integer|proteus.Pane)? split or anchor at this pane instead of the focused one
---@field on_event fun(ev: proteus.UiEvent, s: proteus.Surface)?

---@class proteus.Surface
---@field id integer
local Surface = {}
---Show `lines` (rows from the top).
---@param lines proteus.Line[]
---@param opts { cursor: integer[]?, background: proteus.Color? }? cursor = { col, row } (1-based)
function Surface:draw(lines, opts) end
function Surface:close() end
function Surface:focus() end
---@return integer? cols
---@return integer? rows
function Surface:size() end

---@alias proteus.Mode "normal"|"locked"|"menu"|"pane"|"tab"|"resize"|"move"|"scroll"|"session"

---@class proteus
---@field version string
local p = {}

---Set options; later calls override earlier keys. Only while the config loads.
---@param cfg proteus.Config
function p.config(cfg) end

---Bind a key in a mode to an action name (`proteus --list-actions`), a
---function, or "none"/false to unbind. Only while the config loads.
---@param mode proteus.Mode
---@param key string e.g. "alt+g", "ctrl+shift+k", "f5"
---@param action string|false|fun(ctx: proteus.Ctx)
function p.keymap(mode, key, action) end

---Run `f` on an event.
---@param event proteus.Event
---@param f fun(ev: proteus.EventData)
function p.on(event, f) end

---Run an action by name on the focused pane.
---@param name string
function p.run_action(name) end

---A message in the window (top right).
---@param text string
---@param opts { level: ("info"|"error")?, timeout: number? }?
function p.notify(text, opts) end

---Run `f` once after `secs` seconds.
---@param secs number
---@param f fun()
---@return proteus.Timer
function p.after(secs, f) end

---Run `f` every `secs` seconds until stopped.
---@param secs number
---@param f fun()
---@return proteus.Timer
function p.every(secs, f) end

p.panes = {}
---@return proteus.Pane[]
function p.panes.list() end
---@return proteus.Pane?
function p.panes.focused() end
---@param id integer
---@return proteus.Pane?
function p.panes.get(id) end
---@param opts proteus.SpawnOpts?
---@return proteus.Pane
function p.panes.new_tab(opts) end
---@param opts proteus.SpawnOpts?
---@return proteus.Pane
function p.panes.float(opts) end

p.status = {}
---A tab-bar segment; `f` returns its text (nil or "" hides it). It runs
---after events and once a second, so keep it fast.
---@param side "left"|"right"
---@param f fun(ctx: proteus.Ctx): string?
function p.status.segment(side, f) end

p.palette = {}
---A command palette entry (Ctrl+Shift+P); the same name replaces it.
---@param name string
---@param f fun(ctx: proteus.Ctx)
function p.palette.add(name, f) end

p.ui = {}
---A surface drawn like a plugin's (only in callbacks). Draw it on its
---first `resize` event; it closes when the config reloads.
---@param opts proteus.SurfaceOpts?
---@return proteus.Surface
function p.ui.open(opts) end

return p
